CREATE POLICY "Athlete updates own exercise_logs" ON public.exercise_logs FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.workout_logs wl JOIN public.clients c ON c.id = wl.client_id WHERE wl.id = exercise_logs.workout_log_id AND c.user_id = auth.uid())) WITH CHECK (EXISTS (SELECT 1 FROM public.workout_logs wl JOIN public.clients c ON c.id = wl.client_id WHERE wl.id = exercise_logs.workout_log_id AND c.user_id = auth.uid()));
CREATE POLICY "Athlete deletes own exercise_logs" ON public.exercise_logs FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM public.workout_logs wl JOIN public.clients c ON c.id = wl.client_id WHERE wl.id = exercise_logs.workout_log_id AND c.user_id = auth.uid()));